import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第二册：实践与进步 · Lesson 40 Food and talk","description":"学习 非真实条件句，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 40 Food and talk","description":"学习 非真实条件句，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 非真实条件句，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 39 Am I all right?","link":"/life/english/new-concept/book-2/unit-02/lesson-039"},"next":{"text":"第二册：实践与进步 · Lesson 41 Do you call that a hat?","link":"/life/english/new-concept/book-2/unit-02/lesson-041"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 39 Am I all right?","link":"/life/english/new-concept/book-2/unit-02/lesson-039"},"next":{"text":"第二册：实践与进步 · Lesson 41 Do you call that a hat?","link":"/life/english/new-concept/book-2/unit-02/lesson-041"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-02/lesson-040.md","filePath":"life/english/new-concept/book-2/unit-02/lesson-040.md"}'),l={name:"life/english/new-concept/book-2/unit-02/lesson-040.md"};function i(s,e,r,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-40-food-and-talk" tabindex="-1">第二册：实践与进步 · Lesson 40 Food and talk <a class="header-anchor" href="#第二册-实践与进步-·-lesson-40-food-and-talk" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 40 Food and talk&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>聚餐时提问过密会让别人难以回答；练习反事实假设与更合适的交流选择。本课的语言观察是：If I knew ... I would ... 是对当前知识不足的假设，不是昨天发生的事。would 后接原形，不放进通常的 if 条件部分。完成学习后，请写三句宴会交流反思，用一个假设句说明可以怎样改善提问。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>dinner</td><td>/ˈdɪnə/</td><td>n.</td><td>晚餐</td><td>a family dinner</td></tr><tr><td>guest</td><td>/ɡest/</td><td>n.</td><td>客人</td><td>welcome a guest</td></tr><tr><td>answer</td><td>/ˈɑːnsə/</td><td>n.</td><td>回答</td><td>a brief answer</td></tr><tr><td>topic</td><td>/ˈtɒpɪk/</td><td>n.</td><td>话题</td><td>change the topic</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>make conversation — 交谈、找话题，通常不用 a</li><li>ask about somebody&#39;s work — 询问某人的工作</li></ul><h2 id="语法讲解-非真实条件句" tabindex="-1">语法讲解：非真实条件句 <a class="header-anchor" href="#语法讲解-非真实条件句" aria-label="Permalink to &quot;语法讲解：非真实条件句&quot;">​</a></h2><p>与现在事实不同或可能性较小的假设常用 if 加过去式，主句用 would/could 加原形；与过去事实相反则用 if 加 had done，主句用 would/could have done。这里的过去形式主要表达距离感，不总指过去时间。be 在正式假设中可用 were。选择句型前先确定假设发生的时间，再检查结果的时间，不要把真实未来条件与虚拟假设混用。本课应用：If I knew ... I would ... 是对当前知识不足的假设，不是昨天发生的事。would 后接原形，不放进通常的 if 条件部分。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>If I knew more about her work, I would ask better questions.</p></blockquote><p>如果我更了解她的工作，我就会问出更好的问题。</p><p>knew 表非真实现在假设，would ask 表假设结果；better 是 good 的比较级。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>If I would know 通常不能表达这种标准假设；用 If I knew。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 knew 与 would ask，突出假设条件；questions 的词尾 /z/ 保持清楚。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>If I knew more about her work, I would ask better questions. Instead, I asked about the meal. She smiled and recommended a local restaurant.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句宴会交流反思，用一个假设句说明可以怎样改善提问。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：knew 表非真实现在假设，would ask 表假设结果；better 是 good 的比较级。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：If I would know 通常不能表达这种标准假设；用 If I knew。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 know：If I ___ more, I would ask better questions.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> knew</p><p><strong>解析：</strong> 当前非真实假设的 if 从句用过去式。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>说话者最后选择了什么话题？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The meal.</p><p><strong>解析：</strong> instead 表示改用一个实际可谈的话题。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>补全：If she had more time, she ___ explain it.（would/will）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> would</p><p><strong>解析：</strong> 与当前事实相距的假设结果使用 would。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：非真实条件句。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-039">上一课</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-02/lesson-041">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const k=a(l,[["render",i]]);export{p as __pageData,k as default};
